[metadata] {"type": "update", "filePath": "/workspace/repo/resolving/npm-resolver/src/parseBareSpecifier.ts", "content": "import { PnpmError } from '@pnpm/error'
import { parseJsrSpecifier } from '@pnpm/resolving.jsr-specifier-parser'
import parseNpmTarballUrl from 'parse-npm-tarball-url'
import getVersionSelectorType from 'version-selector-type'

export interface RegistryPackageSpec {
  type: 'tag' | 'version' | 'range'
  name: string
  fetchSpec: string
  normalizedBareSpecifier?: string
}

export function parseBareSpecifier (
  bareSpecifier: string,
  alias: string | undefined,
  defaultTag: string,
  registry: string
): RegistryPackageSpec | null {
  let name = alias
  if (bareSpecifier.startsWith('npm:')) {
    bareSpecifier = bareSpecifier.slice(4)
    // When an alias is provided and the value after `npm:` is a bare semver
    // range/version (e.g. `npm:^1.0.0`), use the alias as the package name
    // instead of trying to parse a name out of the range.
    const bareSelectorType = alias ? getVersionSelectorType(bareSpecifier)?.type : undefined
    if (alias && (bareSelectorType === 'range' || bareSelectorType === 'version')) {
      name = alias
    } else {
      const index = bareSpecifier.lastIndexOf('@')
      if (index < 1) {
        name = bareSpecifier
        bareSpecifier = defaultTag
      } else {
        name = bareSpecifier.slice(0, index)
        bareSpecifier = bareSpecifier.slice(index + 1)
      }
    }
  }
  if (name) {
    const selector = getVersionSelectorType(bareSpecifier)
    if (selector != null) {
      return {
        fetchSpec: selector.normalized,
        name,
        type: selector.type,
      }
    }
  }
  if (bareSpecifier.startsWith(registry)) {
    const pkg = parseNpmTarballUrl.default(bareSpecifier)
    if (pkg != null) {
      return {
        fetchSpec: pkg.version,
        name: pkg.name,
        normalizedBareSpecifier: bareSpecifier,
        type: 'version',
      }
    }
  }
  return null
}

export interface JsrRegistryPackageSpec extends RegistryPackageSpec {
  jsrPkgName: string
}

export function parseJsrSpecifierToRegistryPackageSpec (
  rawSpecifier: string,
  alias: string | undefined,
  defaultTag: string
): JsrRegistryPackageSpec | null {
  const spec = parseJsrSpecifier(rawSpecifier, alias)
  if (!spec?.npmPkgName) return null

  const selector = getVersionSelectorType(spec.versionSelector ?? defaultTag)
  if (selector == null) return null

  return {
    fetchSpec: selector.normalized,
    name: spec.npmPkgName,
    type: selector.type,
    jsrPkgName: spec.jsrPkgName,
  }
}

/**
 * The built-in named registries that pnpm ships with. Exported so that other
 * packages can merge user-defined aliases on top of it.
 */
export const BUILTIN_NAMED_REGISTRIES: Readonly<Record<string, string>> = Object.freeze({
  gh: 'https://npm.pkg.github.com/',
})

/**
 * Prefixes that are reserved for other resolvers/protocols and must never be
 * treated as named-registry aliases, even if a user were to define one with the
 * same name.
 */
const RESERVED_NAMED_REGISTRY_SCHEMES = new Set<string>([
  'npm',
  'jsr',
  'catalog',
  'workspace',
  'github',
])

export interface NamedRegistryPackageSpec extends RegistryPackageSpec {
  registryName: string
}

export function parseNamedRegistrySpecifierToRegistryPackageSpec (
  rawSpecifier: string,
  knownRegistryNames: ReadonlySet<string>,
  packageAlias: string | undefined,
  defaultTag: string
): NamedRegistryPackageSpec | null {
  const colonIndex = rawSpecifier.indexOf(':')
  if (colonIndex < 1) return null
  const registryName = rawSpecifier.slice(0, colonIndex)
  if (RESERVED_NAMED_REGISTRY_SCHEMES.has(registryName)) return null
  if (!knownRegistryNames.has(registryName)) return null

  const body = rawSpecifier.slice(colonIndex + 1)

  let name: string
  let versionSelector: string

  const bodySelectorType = getVersionSelectorType(body)?.type
  if (bodySelectorType === 'range' || bodySelectorType === 'version') {
    // The specifier is only a version selector (e.g. `gh:^1.0.0`). The package
    // name cannot be determined without a package alias.
    if (!packageAlias) return null
    name = packageAlias
    versionSelector = body
  } else {
    const index = body.lastIndexOf('@')
    if (index < 1) {
      name = body
      versionSelector = defaultTag
    } else {
      name = body.slice(0, index)
      versionSelector = body.slice(index + 1)
    }
    if (!isValidNamedRegistryPackageName(name)) {
      throw new PnpmError(
        'INVALID_NAMED_REGISTRY_PACKAGE_NAME',
        `Cannot parse a package name from the named-registry specifier '${registryName}:${body}'`
      )
    }
  }

  const selector = getVersionSelectorType(versionSelector)
  if (selector == null) return null

  return {
    fetchSpec: selector.normalized,
    name,
    type: selector.type,
    registryName,
  }
}

function isValidNamedRegistryPackageName (name: string): boolean {
  if (name.length === 0) return false
  if (name.startsWith('@')) {
    const slashIndex = name.indexOf('/')
    // A scoped name must be `@scope/pkg` with non-empty scope and package parts
    // and no stray `@` after the leading one.
    if (slashIndex < 2 || slashIndex === name.length - 1) return false
    if (name.indexOf('@', 1) !== -1) return false
  }
