 * Prefixes that are reserved for other resolvers/protocols and must never be
 * treated as named-registry aliases, even if a user were to define one with the
 * same name.
 */
const RESERVED_NAMED_REGISTRY_SCHEMES = new Set<string>([
  'npm',
  'jsr',
  'catalog',
  'workspace',
  'github',
])

export interface NamedRegistryPackageSpec extends RegistryPackageSpec {
  registryName: string
}

export function parseNamedRegistrySpecifierToRegistryPackageSpec (
  rawSpecifier: string,
  knownRegistryNames: ReadonlySet<string>,
  packageAlias: string | undefined,
  defaultTag: string
): NamedRegistryPackageSpec | null {
  const colonIndex = rawSpecifier.indexOf(':')
  if (colonIndex < 1) return null
  const registryName = rawSpecifier.slice(0, colonIndex)
  if (RESERVED_NAMED_REGISTRY_SCHEMES.has(registryName)) return null
  if (!knownRegistryNames.has(registryName)) return null

