  if (selector == null) return null

  return {
    fetchSpec: selector.normalized,
    name,
    type: selector.type,
    registryName,
  }
}

function isValidNamedRegistryPackageName (name: string): boolean {
  if (name.length === 0) return false
  if (name.startsWith('@')) {
    const slashIndex = name.indexOf('/')
    // A scoped name must be `@scope/pkg` with non-empty scope and package parts
    // and no stray `@` after the leading one.
    if (slashIndex < 2 || slashIndex === name.length - 1) return false
    if (name.indexOf('@', 1) !== -1) return false
  }
  return true
}
